final class Person {
  private val _courses = scala.collection.mutable.ArrayBuffer.empty[Course]

  def courses: collection.immutable.Seq[Course] = _courses.toList   // snapshot, immutable type

  def addCourse(course: Course): Unit = {
    require(course.accepted)
    _courses += course
  }

  def removeCourse(course: Course): Unit = { _courses -= course }
}
